import{_ as n,a0 as p,w as o,s as d,ao as r,I as l,x as s,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"如何使用 GPG 加解密文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 GPG 加解密文件 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 GPG 加解密文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 GPG 加解密文件 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171024 How to Encrypt and Decrypt Individual Files With GPG","title":"如何使用 GPG 加解密文件","tag":"201712","desc":""},"relativePath":"201712/20171024 How to Encrypt and Decrypt Individual Files With GPG.md","filePath":"[post].md"}'),h={name:"201712/20171024 How to Encrypt and Decrypt Individual Files With GPG.md"};function g(k,i,c,u,b,f){const t=p("Link");return o(),d("div",null,[i[13]||(i[13]=r('<h1 id="如何使用-gpg-加解密文件" tabindex="-1">如何使用 GPG 加解密文件 <a class="header-anchor" href="#如何使用-gpg-加解密文件" aria-label="Permalink to “如何使用 GPG 加解密文件”">​</a></h1><p>目标：使用 GPG 加密文件</p><p>发行版：适用于任何发行版</p><p>要求：安装了 GPG 的 Linux 或者拥有 root 权限来安装它。</p><p>难度：简单</p><p>约定：</p><ul><li><code>#</code> - 需要使用 root 权限来执行指定命令，可以直接使用 root 用户来执行，也可以使用 <code>sudo</code> 命令</li><li><code>$</code> - 可以使用普通用户来执行指定命令</li></ul><h3 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h3><p>加密非常重要。它对于保护敏感信息来说是必不可少的。你的私人文件应该要被加密，而 GPG 提供了很好的解决方案。</p><h3 id="安装-gpg" tabindex="-1">安装 GPG <a class="header-anchor" href="#安装-gpg" aria-label="Permalink to “安装 GPG”">​</a></h3><p>GPG 的使用非常广泛。你在几乎每个发行版的仓库中都能找到它。如果你还没有安装它，那现在就来安装一下吧。</p><p><strong>Debian/Ubuntu</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install gnupg</span></span></code></pre></div><p><strong>Fedora</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># dnf install gnupg2</span></span></code></pre></div><p><strong>Arch</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pacman -S gnupg</span></span></code></pre></div><p><strong>Gentoo</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># emerge --ask app-crypt/gnupg</span></span></code></pre></div><h3 id="创建密钥" tabindex="-1">创建密钥 <a class="header-anchor" href="#创建密钥" aria-label="Permalink to “创建密钥”">​</a></h3><p>你需要一个密钥对来加解密文件。如果你为 SSH 已经生成过了密钥对，那么你可以直接使用它。如果没有，GPG 包含工具来生成密钥对。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --full-generate-key</span></span></code></pre></div><p>GPG 有一个命令行程序可以帮你一步一步的生成密钥。它还有一个简单得多的工具，但是这个工具不能让你设置密钥类型，密钥的长度以及过期时间，因此不推荐使用这个工具。</p><p>GPG 首先会询问你密钥的类型。没什么特别的话选择默认值就好。</p><p>下一步需要设置密钥长度。<code>4096</code> 是一个不错的选择。</p><p>之后，可以设置过期的日期。 如果希望密钥永不过期则设置为 <code>0</code>。</p><p>然后，输入你的名称。</p><p>最后，输入电子邮件地址。</p><p>如果你需要的话，还能添加一个注释。</p><p>所有这些都完成后，GPG 会让你校验一下这些信息。</p><p>GPG 还会问你是否需要为密钥设置密码。这一步是可选的， 但是会增加保护的程度。若需要设置密码，则 GPG 会收集你的操作信息来增加密钥的健壮性。 所有这些都完成后， GPG 会显示密钥相关的信息。</p><h3 id="加密的基本方法" tabindex="-1">加密的基本方法 <a class="header-anchor" href="#加密的基本方法" aria-label="Permalink to “加密的基本方法”">​</a></h3><p>现在你拥有了自己的密钥，加密文件非常简单。 使用下面的命令在 <code>/tmp</code> 目录中创建一个空白文本文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch /tmp/test.txt</span></span></code></pre></div><p>然后用 GPG 来加密它。这里 <code>-e</code> 标志告诉 GPG 你想要加密文件， <code>-r</code> 标志指定接收者。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg -e -r &quot;Your Name&quot; /tmp/test.txt</span></span></code></pre></div><p>GPG 需要知道这个文件的接收者和发送者。由于这个文件给是你的，因此无需指定发送者，而接收者就是你自己。</p><h3 id="解密的基本方法" tabindex="-1">解密的基本方法 <a class="header-anchor" href="#解密的基本方法" aria-label="Permalink to “解密的基本方法”">​</a></h3><p>你收到加密文件后，就需要对它进行解密。 你无需指定解密用的密钥。 这个信息被编码在文件中。 GPG 会尝试用其中的密钥进行解密。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg -d /tmp/test.txt.gpg</span></span></code></pre></div><h3 id="发送文件" tabindex="-1">发送文件 <a class="header-anchor" href="#发送文件" aria-label="Permalink to “发送文件”">​</a></h3><p>假设你需要发送文件给别人。你需要有接收者的公钥。 具体怎么获得密钥由你自己决定。 你可以让他们直接把公钥发送给你， 也可以通过密钥服务器来获取。</p><p>收到对方公钥后，导入公钥到 GPG 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg --import yourfriends.key</span></span></code></pre></div><p>这些公钥与你自己创建的密钥一样，自带了名称和电子邮件地址的信息。 记住，为了让别人能解密你的文件，别人也需要你的公钥。 因此导出公钥并将之发送出去。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gpg --export -a &quot;Your Name&quot; &gt; your.key</span></span></code></pre></div><p>现在可以开始加密要发送的文件了。它跟之前的步骤差不多， 只是需要指定你自己为发送人。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gpg -e -u &quot;Your Name&quot; -r &quot;Their Name&quot; /tmp/test.txt</span></span></code></pre></div><h3 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to “结语”">​</a></h3><p>就这样了。GPG 还有一些高级选项， 不过你在 99% 的时间内都不会用到这些高级选项。 GPG 就是这么易于使用。你也可以使用创建的密钥对来发送和接受加密邮件，其步骤跟上面演示的差不多， 不过大多数的电子邮件客户端在拥有密钥的情况下会自动帮你做这个动作。</p><hr>',51)),l("p",null,[i[1]||(i[1]=s("via: ",-1)),e(t,{href:"https://linuxconfig.org/how-to-encrypt-and-decrypt-individual-files-with-gpg"},{default:a(()=>[...i[0]||(i[0]=[s("https://linuxconfig.org/how-to-encrypt-and-decrypt-individual-files-with-gpg",-1)])]),_:1})]),l("p",null,[i[5]||(i[5]=s("作者：",-1)),e(t,{href:"https://linuxconfig.org"},{default:a(()=>[...i[2]||(i[2]=[s("Nick Congleton",-1)])]),_:1}),i[6]||(i[6]=s(" 译者：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...i[3]||(i[3]=[s("lujun9972",-1)])]),_:1}),i[7]||(i[7]=s(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[4]||(i[4]=[s("wxy",-1)])]),_:1})]),l("p",null,[i[10]||(i[10]=s("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[8]||(i[8]=[s("LCTT",-1)])]),_:1}),i[11]||(i[11]=s(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:a(()=>[...i[9]||(i[9]=[s("Linux 中国",-1)])]),_:1}),i[12]||(i[12]=s(" 荣誉推出",-1))])])}const P=n(h,[["render",g]]);export{m as __pageData,P as default};
